  'TIWYCF': 'calvin harris this is what you came for official video',
  'Faded': 'alan walker faded official video',
  'AyVamos': 'j balvin ay vamos official video',
};
const out = {};
for (const [k, q] of Object.entries(queries)) {
  try {
    const r = await fetch('https://www.youtube.com/results?search_query=' + encodeURIComponent(q));
    const t = await r.text();
    const m = [...t.matchAll(/"videoId":"([\w-]{11})","thumbnail".*?"title":\{"runs":\[\{"text":"(.*?)"\}/g)];
    const seen = new Set(); const list = [];
    for (const mm of m) { if (!seen.has(mm[1])) { seen.add(mm[1]); list.push([mm[1], mm[2]]); } if (list.length >= 5) break; }
    out[k] = list.length ? list : 'no match, len=' + t.length;
  } catch (e) { out[k] = 'ERR ' + e.message; }
}
return out;

